17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.ArrayList;
25	import java.util.Collection;
26	import java.util.List;
27	
28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.VisitMapper;
36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
41	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
42	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
43	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
44	import org.springframework.samples.petclinic.rest.api.OwnersApi;
45	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
46	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.PetDto;
48	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitDto;
50	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
51	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
52	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
75	    private static final int MAX_OWNERS_PER_CITY = 50;
76	
77	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
78	    private static final int MAX_OWNERS_PER_DAY = 100;
79	
80	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
81	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
82	
83	    private final ClinicService clinicService;
84	
85	    private final OwnerMapper ownerMapper;
86	
87	    private final PetMapper petMapper;
88	
89	    private final VisitMapper visitMapper;
90	
91	    private final TelephoneNormalizer telephoneNormalizer;
92	
93	    private final AddressNormalizer addressNormalizer;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper,
99	                                 TelephoneNormalizer telephoneNormalizer,
100	                                 AddressNormalizer addressNormalizer) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	        this.telephoneNormalizer = telephoneNormalizer;
106	        this.addressNormalizer = addressNormalizer;
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
112	        Collection<Owner> owners;
113	        if (lastName != null) {
114	            owners = this.clinicService.findOwnerByLastName(lastName);
115	        } else {
116	            owners = this.clinicService.findAllOwners();
117	        }
118	        if (owners.isEmpty()) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        owners.forEach(this::populateHouseholdMemberCount);
122	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
128	        Owner owner = this.clinicService.findOwnerById(ownerId);
129	        if (owner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        populateHouseholdMemberCount(owner);
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        normalizeAndValidate(ownerFieldsDto);
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
143	        owner.setNamesakeCount(countNamesakes(owner));
144	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
145	        assignHousehold(owner, ownerFieldsDto);
146	        this.clinicService.saveOwner(owner);
147	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
148	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
149	        populateHouseholdMemberCount(owner);
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    /**
157	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
158	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
159	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
160	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
161	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
162	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
163	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
164	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
165	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly.
166	     *
167	     * @param ownerFieldsDto the incoming owner payload, mutated in place
168	     * @throws MissingOwnerFieldsException if any required field is missing or blank
169	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
170	     */
171	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
172	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
173	        validateRequiredFields(ownerFieldsDto);
174	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
175	        ownerFieldsDto.setTelephone(telephone);
176	        requireUniqueTelephone(telephone);
177	        requireUniqueHousehold(ownerFieldsDto);
178	        requireCityHasCapacity(ownerFieldsDto.getCity());
179	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
180	        ownerFieldsDto.setRegistrationDate(registrationDate);
181	        requireDailyLimitNotReached(registrationDate);
182	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
183	    }
184	
185	    /**
186	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
187	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
188	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day.
189	     *
190	     * @param ownerFieldsDto the incoming owner payload
191	     * @return the effective registration date rolled forward onto a business day
192	     */
193	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
194	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
195	        if (effective == null) {
196	            effective = LocalDate.now();
197	        }
198	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
199	            effective = effective.plusDays(1);
200	        }
201	        return effective;
202	    }
203	
204	    /**
205	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
206	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
207	     * further owner may be created for that day.
208	     *
209	     * @param registrationDate the adjusted business-day registration date of the owner being created
210	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
211	     */
212	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
213	        long createdThatDay = this.clinicService.findAllOwners().stream()
214	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
215	            .count();
216	        if (createdThatDay >= MAX_OWNERS_PER_DAY) {
217	            throw new DailyOwnerLimitExceededException(
218	                "the maximum number of owners for today has already been reached");
219	        }
220	    }
221	
222	    /**
223	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
224	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
225	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
226	     * reflects only owners that predate it.
227	     *
228	     * @param registrationDate the adjusted business-day registration date of the owner being created
229	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
230	     */
231	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
232	        long createdThatDay = this.clinicService.findAllOwners().stream()
233	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
234	            .count();
235	        return createdThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
236	    }
237	
238	    /**
239	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
240	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
241	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
242	     * city (e.g. {@code LON-SMI-0007}).
243	     *
244	     * @param city     the owner's city
245	     * @param lastName the owner's last name
246	     * @return the generated customer code
247	     */
248	    private String generateCustomerCode(String city, String lastName) {
249	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
250	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
251	        int sequence = (int) this.clinicService.findAllOwners().stream()
252	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
253	            .count() + 1;
254	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
255	    }
256	
257	    /**
258	     * Counts how many existing owners already share the given owner's first and last name, compared
259	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
260	     * create; it is zero when the owner's name is unique.
261	     *
262	     * @param owner the newly mapped owner about to be saved
263	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
264	     */
265	    private int countNamesakes(Owner owner) {
266	        String firstName = owner.getFirstName();
267	        String lastName = owner.getLastName();
268	        return (int) this.clinicService.findAllOwners().stream()
269	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
270	                && lastName.equalsIgnoreCase(existing.getLastName()))
271	            .count();
272	    }
273	
274	    /**
275	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
276	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
277	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
278	     *
279	     * @param ownerFieldsDto the owner payload to validate
280	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
281	     */
282	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
283	        List<String> missingFields = new ArrayList<>();
284	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
285	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
286	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
287	        requireText(missingFields, "city", ownerFieldsDto.getCity());
288	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
289	        if (!missingFields.isEmpty()) {
290	            throw new MissingOwnerFieldsException(missingFields);
291	        }
292	    }
293	
294	    private void requireText(List<String> missingFields, String fieldName, String value) {
295	        if (value == null || value.isBlank()) {
296	            missingFields.add(fieldName);
297	        }
298	    }
299	
300	    /**
301	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
302	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
303	     * (blank or {@code null}) email is left untouched, since the field is optional.
304	     *
305	     * @param email the raw email value from the request, may be {@code null}
306	     * @return the lower-cased email, or the original value when none was supplied
307	     */
308	    private String normalizeEmail(String email) {
309	        if (email == null || email.isBlank()) {
310	            return email;
311	        }
312	        return email.toLowerCase();
313	    }
314	
315	    /**
316	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
317	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
318	     * originally formatted.
319	     *
320	     * @param telephone the normalized telephone of the owner being created
321	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
322	     */
323	    private void requireUniqueTelephone(String telephone) {
324	        boolean inUse = this.clinicService.findAllOwners().stream()
325	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
326	            .anyMatch(telephone::equals);
327	        if (inUse) {
328	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
329	        }
330	    }
331	
332	    /**
333	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
334	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
335	     *
336	     * @param city the city of the owner being created
337	     * @throws OwnerCityFullException if the city already contains 50 or more owners
338	     */
339	    private void requireCityHasCapacity(String city) {
340	        long cityOwners = this.clinicService.findAllOwners().stream()
341	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
342	            .count();
343	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
344	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
345	        }
346	    }
347	
348	    /**
349	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
350	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
351	     *
352	     * @param ownerFieldsDto the incoming owner payload
353	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
354	     *                                 set {@code sharesHousehold}
355	     */
356	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
357	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
358	            return;
359	        }
360	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
361	            throw new DuplicateOwnerException(
362	                "an owner with the same last name and address already exists in this household");
363	        }
364	    }
365	
366	    /**
367	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
368	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
369	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
370	     * incidental formatting differences and abbreviation variants do not affect membership.
371	     *
372	     * @param ownerFieldsDto the incoming owner payload
373	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
374	     *         them; empty when none match
375	     */
376	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
377	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
378	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
379	        return this.clinicService.findAllOwners().stream()
380	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
381	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
382	            .toList();
383	    }
384	
385	    /**
386	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
387	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
388	     *
389	     * @param value the raw field value, may be {@code null}
390	     * @return the whitespace-collapsed value, or an empty string when {@code null}
391	     */
392	    private String collapseWhitespace(String value) {
393	        if (value == null) {
394	            return "";
395	        }
396	        return value.strip().replaceAll("\\s+", " ");
397	    }
398	
399	    /**
400	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
401	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
402	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
403	     * identifier is derived deterministically from the household's last name and address, so every member of the same
404	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
405	     * feature and still lack the identifier are backfilled so the whole household shares it.
406	     *
407	     * @param owner          the newly mapped owner about to be saved
408	     * @param ownerFieldsDto the incoming owner payload
409	     */
410	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
411	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
412	            return;
413	        }
414	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
415	        if (members.isEmpty()) {
416	            return;
417	        }
418	        String householdId = generateHouseholdId(ownerFieldsDto);
419	        owner.setHouseholdId(householdId);
420	        for (Owner member : members) {
421	            if (!householdId.equals(member.getHouseholdId())) {
422	                member.setHouseholdId(householdId);
423	                this.clinicService.saveOwner(member);
424	            }
425	        }
426	    }
427	
428	    /**
429	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
430	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
431	     * of those fields, it is identical for every owner in the same household and never changes over time.
432	     *
433	     * @param ownerFieldsDto the incoming owner payload
434	     * @return the household identifier
435	     */
436	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
437	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
438	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
439	        try {
440	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
441	            StringBuilder hex = new StringBuilder();
442	            for (int i = 0; i < 6; i++) {
443	                hex.append(String.format("%02X", digest[i]));
444	            }
445	            return "HH-" + hex;
446	        } catch (NoSuchAlgorithmException ex) {
447	            throw new IllegalStateException("SHA-256 is not available", ex);
448	        }
449	    }
450	
451	    /**
452	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
453	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
454	     * household is counted as a household of one. This drives the {@code GOLD} membership tier, awarded once a household
455	     * reaches three or more members.
456	     *
457	     * @param owner the owner whose household size should be resolved
458	     */
459	    private void populateHouseholdMemberCount(Owner owner) {
460	        String householdId = owner.getHouseholdId();
461	        if (householdId == null) {
462	            owner.setHouseholdMemberCount(1);
463	            return;
464	        }
465	        long members = this.clinicService.findAllOwners().stream()
466	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
467	            .count();
468	        owner.setHouseholdMemberCount((int) members);
469	    }
470	
471	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
472	    @Override
473	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
474	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
475	        if (currentOwner == null) {
476	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
477	        }
478	        currentOwner.setAddress(ownerFieldsDto.getAddress());
479	        currentOwner.setCity(ownerFieldsDto.getCity());
480	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
481	        currentOwner.setLastName(ownerFieldsDto.getLastName());
482	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
483	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
484	        this.clinicService.saveOwner(currentOwner);
485	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
486	    }
487	
488	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
489	    @Transactional
490	    @Override
491	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
492	        Owner owner = this.clinicService.findOwnerById(ownerId);
493	        if (owner == null) {
494	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
495	        }
496	        this.clinicService.deleteOwner(owner);
497	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
498	    }
499	
500	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
501	    @Override
502	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
503	        Owner owner = this.clinicService.findOwnerById(ownerId);
504	        if (owner == null) {
505	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
506	        }
507	        HttpHeaders headers = new HttpHeaders();
508	        Pet pet = petMapper.toPet(petFieldsDto);
509	        owner.setId(ownerId);
510	        pet.setOwner(owner);
511	        pet.getType().setName(null);
512	        this.clinicService.savePet(pet);
513	        PetDto petDto = petMapper.toPetDto(pet);
514	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
515	            .buildAndExpand(pet.getId()).toUri());
516	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
517	    }
518	
519	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
520	    @Override
521	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
522	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
523	        if (currentOwner != null) {
524	            Pet currentPet = this.clinicService.findPetById(petId);
525	            if (currentPet != null) {
526	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
527	                currentPet.setName(petFieldsDto.getName());
528	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
529	                this.clinicService.savePet(currentPet);
530	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
531	            }
532	        }
533	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
534	    }
535	
536	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
537	    @Override
538	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
539	        HttpHeaders headers = new HttpHeaders();
540	        Visit visit = visitMapper.toVisit(visitFieldsDto);
541	        Pet pet = new Pet();
542	        pet.setId(petId);
543	        visit.setPet(pet);
544	        this.clinicService.saveVisit(visit);
545	        VisitDto visitDto = visitMapper.toVisitDto(visit);
546	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
547	            .buildAndExpand(visit.getId()).toUri());
548	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
549	    }
550	
551	
552	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
553	    @Override
554	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
555	        Owner owner = this.clinicService.findOwnerById(ownerId);
556	        if (owner != null) {
557	            Pet pet = owner.getPet(petId);
558	            if (pet != null) {
559	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
560	            }
561	        }
562	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
563	    }
564	}
